+import sales from './sales.json' with {type:'json'};
+
+const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
+
+function isValidISODate(value) {
+  if (typeof value !== 'string' || !ISO_DATE_RE.test(value)) return false;
+  const date = new Date(value + 'T00:00:00Z');
+  if (isNaN(date.getTime())) return false;
+  // Guard against dates that parse but don't round-trip (e.g. invalid month/day)
+  return date.toISOString().slice(0, 10) === value;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'sales_report',
+      description: 'Sum sales rows inclusively within a [start_date, end_date] date range and return the total amount and row count.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          start_date: { type: 'string', description: 'Inclusive start date as an ISO date string (YYYY-MM-DD).' },
+          end_date: { type: 'string', description: 'Inclusive end date as an ISO date string (YYYY-MM-DD).' }
+        },
+        required: ['start_date', 'end_date'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'sales_report') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+
+  const allowed = new Set(['start_date', 'end_date']);
+  const extra = Object.keys(args).filter(k => !allowed.has(k));
+  if (extra.length > 0) {
+    throw new Error('Unexpected field(s): ' + extra.join(', '));
+  }
+
+  const { start_date, end_date } = args;
+
+  if (start_date === undefined || end_date === undefined) {
+    throw new Error('start_date and end_date are required');
+  }
+
+  if (!isValidISODate(start_date)) {
+    throw new Error('start_date must be a valid ISO date string (YYYY-MM-DD)');
+  }
+  if (!isValidISODate(end_date)) {
+    throw new Error('end_date must be a valid ISO date string (YYYY-MM-DD)');
+  }
+
+  if (new Date(start_date + 'T00:00:00Z').getTime() > new Date(end_date + 'T00:00:00Z').getTime()) {
+    throw new Error('start_date must not be after end_date');
+  }
+
+  const startMs = new Date(start_date + 'T00:00:00Z').getTime();
+  const endMs = new Date(end_date + 'T00:00:00Z').getTime();
+
+  let total = 0;
+  let count = 0;
+  for (const row of sales) {
+    if (!isValidISODate(row.date)) continue;
+    const rowMs = new Date(row.date + 'T00:00:00Z').getTime();
+    if (rowMs >= startMs && rowMs <= endMs) {
+      total += row.amount;
+      count += 1;
+    }
+  }
+
+  const text = 'Total amount: ' + total + '\nRow count: ' + count;
+  return { content: [{ type: 'text', text }] };
+}
